[{"order":1,"type":"heading","text":"Foundry and Hardhat Testing Frameworks in Solidity"},{"order":2,"type":"paragraph","text":"Testing is a critical phase in smart contract development. Foundry and Hardhat are the two most prominent development environments used by Solidity engineers today. This tutorial compares their testing paradigms and demonstrates how to write robust unit tests in both frameworks."},{"order":3,"type":"heading","text":"Understanding the Frameworks"},{"order":4,"type":"paragraph","text":"Hardhat is JavaScript/TypeScript-based, utilizing Mocha and Chai for testing, which makes it ideal for developers who prefer a rich ecosystem of Node.js plugins. Foundry is written in Rust and allows developers to write tests directly in Solidity, offering blazing-fast execution speeds and advanced fuzzing capabilities out of the box."},{"order":5,"type":"heading","text":"Setting Up the Target Contract"},{"order":6,"type":"paragraph","text":"Before writing tests, consider a simple Vault contract that allows users to deposit and withdraw Ether."},{"order":7,"type":"code","text":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract Vault {
    mapping(address => uint256) public balances;

    event Deposit(address indexed depositor, uint256 amount);
    event Withdraw(address indexed withdrawer, uint256 amount);

    function deposit() external payable {
        require(msg.value > 0, "Zero deposit");
        balances[msg.sender] += msg.value;
        emit Deposit(msg.sender, msg.value);
    }

    function withdraw(uint256 amount) external {
        require(balances[msg.sender] >= amount, "Insufficient balance");
        balances[msg.sender] -= amount;
        (bool success, ) = msg.sender.call{value: amount}("");
        require(success, "Transfer failed");
        emit Withdraw(msg.sender, amount);
    }
}"},{"order":8,"type":"heading","text":"Writing Tests in Foundry (Solidity)"},{"order":9,"type":"paragraph","text":"Foundry uses Forge for testing. Tests are written entirely in Solidity inside the test directory. Foundry also supports cheatcodes (like vm.prank and vm.deal) to manipulate the blockchain state."},{"order":10,"type":"code","text":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/Vault.sol";

contract VaultTest is Test {
    Vault vault;
    address user = makeAddr("user");

    function setUp() public {
        vault = new Vault();
        vm.deal(user, 10 ether);
    }

    function testDeposit() public {
        vm.prank(user);
        vault.deposit{value: 1 ether}();
        assertEq(vault.balances(user), 1 ether);
    }

    function testFailWithdrawTooMuch() public {
        vm.prank(user);
        vault.withdraw(1 ether);
    }
}"},{"order":11,"type":"heading","text":"Writing Tests in Hardhat (JavaScript/TypeScript)"},{"order":12,"type":"paragraph","text":"Hardhat utilizes JavaScript or TypeScript alongside ethers.js and Chai assertions. This allows asynchronous interactions with the local Hardhat EVM network."},{"order":13,"type":"code","text":"const { expect } = require("chai");
const { ethers } = require("hardhat");

describe("Vault Contract", function () {
    let Vault, vault, owner, user;

    beforeEach(async function () {
        [owner, user] = await ethers.getSigners();
        Vault = await ethers.getContractFactory("Vault");
        vault = await Vault.deploy();
    });

    it("Should allow users to deposit Ether", async function () {
        await vault.connect(user).deposit({ value: ethers.parseEther("1.0") });
        expect(await vault.balances(user.address)).to.equal(ethers.parseEther("1.0"));
    });

    it("Should fail when withdrawing more than balance", async function () {
        await expect(
            vault.connect(user).withdraw(ethers.parseEther("1.0"))
        ).to.be.revertedWith("Insufficient balance");
    });
});"},{"order":14,"type":"heading","text":"Comparing Execution and Features"},{"order":15,"type":"bullet_point","text":"Speed: Foundry executes tests significantly faster because it compiles and runs natively without Node.js overhead."},{"order":16,"type":"bullet_point","text":"Language: Foundry uses Solidity for testing, keeping developers in the same language. Hardhat uses JS/TS, bridging smart contracts with web3 frontend integration testing."},{"order":17,"type":"bullet_point","text":"Fuzzing: Foundry provides native invariant and fuzz testing out of the box, whereas Hardhat relies more heavily on plugins like Echidna or custom scripts for advanced fuzzing."},{"order":18,"type":"heading","text":"Conclusion"},{"order":19,"type":"paragraph","text":"Both Foundry and Hardhat are industry standards. Choosing between them depends on your team's familiarity with Rust/Solidity versus JavaScript/TypeScript, and whether your workflow benefits from Foundry's raw execution speed or Hardhat's extensive plugin ecosystem."}]
